S.append(TB(c,B+' · 1','Bảng theo dõi vòng while',['Lần','i trước','i &lt;= 3 ?','Việc làm','i sau'],[['1','1','đúng','in “lan 1”','2'],['2','2','đúng','in “lan 2”','3'],['3','3','đúng','in “lan 3”','4'],['4','4','<b>sai</b>','thoát vòng lặp','4']],note=KEY('Ba bước của vòng while: <b>khởi tạo</b> (i = 1) – <b>kiểm tra điều kiện</b> – <b>cập nhật</b> (i += 1). Thiếu một bước là lỗi.')))
