S.append(S2(c,B+' · 2','Tổng các chữ số, đếm chữ số',card('Mẫu chương trình',P('<b>Tổng chữ số</b>: cộng <code>n % 10</code> vào biến tổng.','<b>Đếm chữ số</b>: mỗi lần bỏ một chữ số thì đếm +1.','Có thể giải bằng <code>str(n)</code> nhưng <b>với bài số học</b> nên dùng % và //.')),CODE('n = int(input())\ntong = dem = 0\nwhile n > 0:\n    tong += n % 10\n    n //= 10\n    dem += 1\nprint(tong, dem)',22)+R('n = int(input())\ntong = dem = 0\nwhile n > 0:\n    tong += n % 10\n    n //= 10\n    dem += 1\nprint(tong, dem)','90879\n',24,'Kết quả (n = 90879)')+KEY('9 + 0 + 8 + 7 + 9 = 33; có 5 chữ số. Cách ngắn: <code>sum(map(int, str(n)))</code>.')))
S.append(S2(c,B+' · 2','Đảo ngược số và kiểm tra số đối xứng',card('Công thức then chốt',P('Đảo số: <code>dao = dao * 10 + n % 10</code> (dịch dao sang trái một hàng rồi thêm chữ số mới).','Số đối xứng (palindrome): <b>bằng số đảo</b> của chính nó.','<b>Phải lưu n gốc</b> trước khi lặp vì n bị “ăn dần”.')),CODE('n = int(input())\ngoc = n\ndao = 0\nwhile n > 0:\n    dao = dao * 10 + n % 10\n    n //= 10\nprint(dao, goc == dao)',21)+R('n = int(input())\ngoc = n\ndao = 0\nwhile n > 0:\n    dao = dao * 10 + n % 10\n    n //= 10\nprint(dao, goc == dao)','12321\n',24,'Kết quả (n = 12321)')))
