S.append(S2(c,B+' · 2','Chữ số lớn nhất, nhỏ nhất, đếm chữ số lẻ',card('Kết hợp vòng lặp và so sánh',P('Mỗi lần lấy <code>c = n % 10</code>, ta so sánh c với giá trị lớn nhất hiện có, hoặc đếm nếu thoả điều kiện.','Khởi tạo lớn nhất bằng <b>−1</b> hoặc <b>0</b>, nhỏ nhất bằng <b>9</b>.')),CODE('n = 5918037\nlon, nho, le = 0, 9, 0\nwhile n > 0:\n    c = n % 10\n    lon = max(lon, c)\n    nho = min(nho, c)\n    if c % 2 == 1:\n        le += 1\n    n //= 10\nprint(lon, nho, le)',21)+R('n = 5918037\nlon, nho, le = 0, 9, 0\nwhile n > 0:\n    c = n % 10\n    lon = max(lon, c)\n    nho = min(nho, c)\n    if c % 2 == 1:\n        le += 1\n    n //= 10\nprint(lon, nho, le)','',24,'Kết quả')+KEY('Số 5918037 có chữ số lẻ: 5, 9, 1, 3, 7 → <b>5</b>.')))
S.append(S2(c,B+' · 2','Đổi số sang cơ số khác bằng chia liên tiếp',card('Nhắc lại và cài đặt',P('Chia n cho cơ số b, <b>lấy dư</b> ghi lại, rồi n //= b. Các số dư đọc <b>từ dưới lên</b> là kết quả.','Ví dụ 13 → nhị phân: 13 : 2 = 6 dư 1; 6 : 2 = 3 dư 0; 3 : 2 = 1 dư 1; 1 : 2 = 0 dư 1 → <b>1101</b>.')),CODE('n = 13\ns = ""\nwhile n > 0:\n    s = str(n % 2) + s\n    n //= 2\nprint(s, bin(13)[2:])',22)+R('n = 13\ns = ""\nwhile n > 0:\n    s = str(n % 2) + s\n    n //= 2\nprint(s, bin(13)[2:])','',24,'Kết quả')+KEY('Ghép <b>chữ số mới vào đầu xâu</b> (<code>str(...) + s</code>) nên không phải đảo lại.')))
S.append(SELF(c,B+' · 2','Tự kiểm tra: while và chữ số','Tính in ra gì? Cho biết số lần lặp.','n = 2750\ns = 0\nwhile n > 0:\n    s = s * 10 + n % 10\n    n = n // 10\nprint(s)',P('n = 2750: lấy 0 → s = 0; n = 275. Lấy 5 → s = 5; n = 27. Lấy 7 → s = 57; n = 2. Lấy 2 → s = 572; n = 0.','Thoát, in <b>572</b>. Vòng lặp chạy <b>4 lần</b>. Số 0 cuối biến mất khi đảo.')+R('n = 2750\ns = 0\nwhile n > 0:\n    s = s * 10 + n % 10\n    n = n // 10\nprint(s)','',24,'Kết quả thật'),20))
