S.append(S2(c,B+' · 3','Ước số và số lượng ước',card('Định nghĩa',P('<b>d là ước của n</b> khi <code>n % d == 0</code>.','Duyệt d từ 1 đến n, đếm và in các ước.','Ví dụ ước của 12: 1, 2, 3, 4, 6, 12 (có 6 ước).')),CODE('n = 12\nuoc = []\nfor d in range(1, n + 1):\n    if n % d == 0:\n        uoc.append(d)\nprint(uoc, len(uoc), sum(uoc))',21)+R('n = 12\nuoc = []\nfor d in range(1, n + 1):\n    if n % d == 0:\n        uoc.append(d)\nprint(uoc, len(uoc), sum(uoc))','',24,'Kết quả')))
S.append(S2(c,B+' · 3','Tăng tốc: chỉ duyệt đến √n',card('Ước đi theo cặp',P('Nếu d là ước thì <b>n // d</b> cũng là ước. Một trong hai số <b>không vượt √n</b>.','Chỉ cần duyệt d từ 1 đến <b>√n</b>, mỗi ước d cho ra cặp (d, n // d).','Với n = 10⁹: từ 10⁹ lần lặp xuống chỉ <b>≈ 31623</b> lần.')),CODE('n = 36\nuoc = set()\nd = 1\nwhile d * d <= n:\n    if n % d == 0:\n        uoc.add(d)\n        uoc.add(n // d)\n    d += 1\nprint(sorted(uoc))',21)+R('n = 36\nuoc = set()\nd = 1\nwhile d * d <= n:\n    if n % d == 0:\n        uoc.add(d)\n        uoc.add(n // d)\n    d += 1\nprint(sorted(uoc))','',24,'Kết quả')+KEY('Dùng <b>set</b> để không đếm trùng khi d = n // d (số chính phương như 36: d = 6).')))
S.append(S2(c,B+' · 3','Kiểm tra số nguyên tố',card('Định nghĩa và thuật toán',P('<b>Số nguyên tố</b>: lớn hơn 1 và chỉ có đúng hai ước là 1 và chính nó.','Thuật toán: <b>n &lt; 2 → không</b>; duyệt d từ 2 đến √n; gặp d chia hết n → <b>hợp số</b>.','Số 2 là số nguyên tố chẵn duy nhất.')),CODE('n = int(input())\nlap = n >= 2\nd = 2\nwhile d * d <= n and lap:\n    if n % d == 0:\n        lap = False\n    d += 1\nprint("nguyen to" if lap else "khong")',20)+R('n = int(input())\nlap = n >= 2\nd = 2\nwhile d * d <= n and lap:\n    if n % d == 0:\n        lap = False\n    d += 1\nprint("nguyen to" if lap else "khong")','97\n',22,'Kết quả (n = 97)')+KEY('Cần xét <b>n &lt; 2</b> (0, 1, âm không phải nguyên tố). Lỗi phổ biến nhất của bài này.')))
S.append(S2(c,B+' · 3','Viết hàm là_nguyên_tố và liệt kê',card('Đóng gói thành hàm',P('Hàm giúp <b>dùng lại</b> nhiều lần. <b>return False</b> ngay khi tìm thấy ước giúp thoát sớm.','Liệt kê các số nguyên tố từ 1 đến 50 và đếm.')),CODE('def nt(n):\n    if n < 2:\n        return False\n    d = 2\n    while d * d <= n:\n        if n % d == 0:\n            return False\n        d += 1\n    return True\n\nds = [i for i in range(1, 51) if nt(i)]\nprint(ds, len(ds))',19)+R('def nt(n):\n    if n < 2:\n        return False\n    d = 2\n    while d * d <= n:\n        if n % d == 0:\n            return False\n        d += 1\n    return True\n\nds = [i for i in range(1, 51) if nt(i)]\nprint(ds, len(ds))','',20,'Kết quả')))
S.append(S2(c,B+' · 3','Phân tích ra thừa số nguyên tố',card('Ý tưởng',P('Chia n cho d = 2, 3, 4… <b>chừng nào còn chia hết</b>, ghi nhận d rồi n //= d.','Khi d * d &gt; n mà n còn &gt; 1 thì <b>n còn lại là số nguyên tố</b>.','Ví dụ 360 = 2³ × 3² × 5.')),CODE('n = 360\nd = 2\nkq = []\nwhile d * d <= n:\n    while n % d == 0:\n        kq.append(d)\n        n //= d\n    d += 1\nif n > 1:\n    kq.append(n)\nprint(kq)',21)+R('n = 360\nd = 2\nkq = []\nwhile d * d <= n:\n    while n % d == 0:\n        kq.append(d)\n        n //= d\n    d += 1\nif n > 1:\n    kq.append(n)\nprint(kq)','',24,'Kết quả')+KEY('Vòng <b>while lồng</b>: vòng trong rút hết thừa số d, vòng ngoài tăng d.')))
S.append(S2(c,B+' · 3','Số hoàn hảo và số chính phương',card('Định nghĩa',P('<b>Số hoàn hảo</b>: bằng <b>tổng các ước thật sự</b> (nhỏ hơn nó). Ví dụ 6 = 1 + 2 + 3; 28 = 1 + 2 + 4 + 7 + 14.','<b>Số chính phương</b>: bằng bình phương một số nguyên, ví dụ 49. Kiểm tra: <code>r = isqrt(n); r * r == n</code>.')),CODE('from math import isqrt\ndef hh(n):\n    return n > 1 and sum(d for d in range(1, n) if n % d == 0) == n\nprint([i for i in range(1, 1000) if hh(i)])\nprint([i for i in (48, 49, 50) if isqrt(i)**2 == i])',20)+R('from math import isqrt\ndef hh(n):\n    return n > 1 and sum(d for d in range(1, n) if n % d == 0) == n\nprint([i for i in range(1, 1000) if hh(i)])\nprint([i for i in (48, 49, 50) if isqrt(i)**2 == i])','',22,'Kết quả')+WARN('Không dùng <code>sqrt(n) == int(sqrt(n))</code> với số rất lớn vì sai số số thực; dùng <b>isqrt</b>.')))
# Euclid
S.append(S2(c,B+' · 4','Thuật toán Euclid tìm ƯCLN',card('Ý tưởng',P('<b>ƯCLN(a, b) = ƯCLN(b, a % b)</b>; dừng khi b = 0 thì ƯCLN là a.','Rất nhanh: số lần lặp chỉ cỡ <b>log</b> của số bé.','<b>BCNN(a, b) = a × b // ƯCLN(a, b)</b>.')),CODE('a, b = 48, 18\nwhile b != 0:\n    a, b = b, a % b\nprint(a)',24)+R('a, b = 48, 18\nwhile b != 0:\n    a, b = b, a % b\nprint(a)','',24,'Kết quả')+KEY('Có thể dùng sẵn <code>math.gcd</code> (và <code>math.lcm</code> từ Python 3.9).')))
S.append(TB(c,B+' · 4','Theo dõi Euclid: a = 48, b = 18',['Lần','a','b','a % b'],[['(đầu)','48','18','12'],['1','18','12','6'],['2','12','6','0'],['3','6','0','dừng']],note=KEY('ƯCLN(48, 18) = <b>6</b>. BCNN = 48 × 18 // 6 = <b>144</b>. Phép gán bộ <code>a, b = b, a % b</code> tính vế phải <b>trước</b> rồi mới gán.')))
S.append(S2(c,B+' · 4','Dãy Collatz: không biết trước số bước',card('Bài toán',P('Bắt đầu từ n. Nếu n chẵn: n = n // 2; nếu lẻ: n = 3n + 1. Lặp đến khi n = 1. <b>Đếm số bước</b>.','Chưa ai chứng minh dãy luôn về 1, nhưng thử đến số rất lớn đều đúng. Rất hợp để minh hoạ <b>while</b>.')),CODE('n = 27\nbuoc = 0\nwhile n != 1:\n    n = n // 2 if n % 2 == 0 else 3 * n + 1\n    buoc += 1\nprint(buoc)',22)+R('n = 27\nbuoc = 0\nwhile n != 1:\n    n = n // 2 if n % 2 == 0 else 3 * n + 1\n    buoc += 1\nprint(buoc)','',24,'Số bước với n = 27')))
S.append(S2(c,B+' · 4','while True và break: đọc đến khi gặp điều kiện dừng',card('Mẫu “vòng lặp vô hạn có kiểm soát”',KEY('Số 0 là <b>lính canh</b> (sentinel), <b>không cộng</b> vào tổng.')+P('<code>while True:</code> lặp mãi, và <b>break</b> thoát khi thoả điều kiện dừng ở giữa thân.','Hợp cho bài nhập đến khi gặp số 0, hay lặp đến khi người dùng nhập đúng.')),CODE('tong = 0\nwhile True:\n    x = int(input())\n    if x == 0:\n        break\n    tong += x\nprint(tong)',21)+R('tong = 0\nwhile True:\n    x = int(input())\n    if x == 0:\n        break\n    tong += x\nprint(tong)','5\n8\n-2\n0\n',22,'Kết quả (nhập 5, 8, −2, 0)')))
S.append(S2(c,B+' · 4','while … else và tìm kiếm',card('else của while',P('Giống for: <b>else chạy khi vòng while kết thúc không do break</b>.','Dùng để báo “không tìm thấy”.')),CODE('a = [4, 9, 2, 7]\ni = 0\nwhile i < len(a):\n    if a[i] > 8:\n        print("co o vi tri", i)\n        break\n    i += 1\nelse:\n    print("khong co")',22)+R('a = [4, 9, 2, 7]\ni = 0\nwhile i < len(a):\n    if a[i] > 8:\n        print("co o vi tri", i)\n        break\n    i += 1\nelse:\n    print("khong co")','',24,'Kết quả')))
S.append(SELF(c,B+' · 4','Tự kiểm tra (HSG): Euclid và chữ số','Cho n = 1000. Đếm số cặp (a, b), 1 ≤ a &lt; b ≤ n, có ƯCLN(a, b) = 1 và a + b = n. Nêu cách nghĩ và kết quả.','from math import gcd\nn = 1000\nt = sum(1 for a in range(1, n) if a < n - a and gcd(a, n - a) == 1)\nprint(t)',P('Vì <b>ƯCLN(a, n − a) = ƯCLN(a, n)</b>, điều kiện trở thành ƯCLN(a, 1000) = 1, tức a nguyên tố cùng nhau với 1000 = 2³·5³.','Số a trong 1..999 nguyên tố cùng nhau với 1000 là φ(1000) = 1000 × (1/2) × (4/5) = 400 (trừ a = 1000 không xét) → có <b>400</b> số a; vì a và 1000 − a ghép cặp nên số cặp a &lt; b là <b>200</b>.')+R('from math import gcd\nn = 1000\nt = sum(1 for a in range(1, n) if a < n - a and gcd(a, n - a) == 1)\nprint(t)','',24,'Kết quả thật'),20))
S.append(SELF(c,B+' · 4','Tự kiểm tra (HSG): số lần lặp while','Tính số lần lặp của đoạn sau và giá trị s.','n = 1000\ns = 0\nwhile n > 0:\n    s += n % 7\n    n //= 7\nprint(s)',P('Viết 1000 trong cơ số 7: 1000 = 2×343 + 314; 314 = 6×49 + 20; 20 = 2×7 + 6 → chữ số: 2, 6, 2, 6 (đọc từ trái) = 2626₇.','Vòng lặp lấy các chữ số cơ số 7 → <b>4 lần lặp</b>, s = 2 + 6 + 2 + 6 = <b>16</b>.')+R('n = 1000\nk = 0\ns = 0\nwhile n > 0:\n    s += n % 7\n    n //= 7\n    k += 1\nprint(s, k)','',24,'Kết quả thật (tổng, số lần)'),20))
S+=END(c,B,['<b>while</b> kiểm tra điều kiện <b>trước</b> mỗi lần lặp; sai ngay thì không chạy lần nào.','Nhớ ba bước: <b>khởi tạo – điều kiện – cập nhật</b>; thiếu cập nhật là vô hạn.','<b>n % 10</b> lấy chữ số cuối, <b>n // 10</b> bỏ chữ số cuối.','Đảo số: <code>dao = dao * 10 + n % 10</code>.','Ước và nguyên tố: chỉ cần duyệt đến <b>√n</b>; nhớ <b>n &lt; 2</b>.','<b>Euclid</b>: <code>a, b = b, a % b</code> đến khi b = 0.'],[('Chữ số cuối','n % 10'),('Bỏ chữ số cuối','n // 10'),('ƯCLN','Euclid'),('Dừng giữa chừng','break')],'Quên cập nhật biến; quên lưu n gốc; quên xét n &lt; 2 khi kiểm tra nguyên tố.',['Điều kiện <code>d * d &lt;= n</code> tránh dùng sqrt số thực.','<code>a, b = b, a % b</code> gán đồng thời.','<b>else</b> của while chạy khi không break.','Đếm lần lặp while bằng cách tính toán, không chạy tay hết.'],['<b>Sàng Eratosthenes</b> tìm mọi số nguyên tố ≤ n.','<b>Hàm Euler φ(n)</b> và số nguyên tố cùng nhau.','<b>Phân tích thừa số nguyên tố</b> nhanh.'],
 [('<code>n // 10</code> của 905?',),('<code>905 % 10</code>?',),('Số lần lặp: <code>i = 5; while i &lt; 5:</code>?',),('ƯCLN(12, 30)?',),('Số 1 có phải số nguyên tố không?',)],
 [('<b>90</b>.',),('<b>5</b>.',),('<b>0</b> lần.',),('<b>6</b>.',),('<b>Không</b> (cần lớn hơn 1).',)],
 [('Mức 1. Nhập n, in tổng các chữ số. Thử 90879.',),('Mức 1. Nhập a, b, in ƯCLN và BCNN. Thử 48 18.',),('Mức 2. Đếm số chữ số 0 của n. Thử 1002030.',),('Mức 2. Đếm các số nguyên tố từ 1 đến n, thử n = 100.',),('Mức 3 (HSG). Tìm các số có ba chữ số bằng tổng lập phương các chữ số (số Armstrong).',),('Mức 3 (HSG). Tìm số nhỏ nhất có đúng 12 ước số. Gợi ý: duyệt n tăng dần, đếm ước đến √n.',)],
 [(V('print(sum(map(int,"90879")))')+'.',),(V('from math import gcd\nprint(gcd(48,18), 48*18//gcd(48,18))')+'.',),(V('n=1002030\nk=0\nwhile n>0:\n    k+= n%10==0\n    n//=10\nprint(k)')+' chữ số 0.',),(V('print(sum(all(i%d for d in range(2,int(i**.5)+1)) for i in range(2,101)))')+' số.',),(V('print([n for n in range(100,1000) if sum(int(c)**3 for c in str(n))==n])')+'.',),(V('n=1\nwhile True:\n    d=0\n    k=1\n    while k*k<=n:\n        if n%k==0:\n            d+=2 if k*k!=n else 1\n        k+=1\n    if d==12: break\n    n+=1\nprint(n)')+' (= 60).',)],hper=2)
